-- Self-serve automations: every agency automation can now be bought at a fixed price (the lowest price of its
-- done-for-you range) and set up by the customer: a plain-language form, their workflow file with their answers
-- already filled in, and a step-by-step guide. The done-for-you setup stays available through the quote form,
-- with its range kept in price_label.
--
-- For each listing: an approved version 1.0.0 (current), the setup form generated from the workflow's Settings
-- node, the apps the workflow really uses, and the price. Generated by `node automations/src/setup.mjs --sql`.

create temporary table self_serve (slug text primary key, manifest jsonb not null, integrations text[] not null, prerequisites text not null, price_minor integer);
insert into self_serve (slug, manifest, integrations, prerequisites) values
  ('ai-lead-generation-follow-up', $m${"schemaVersion":1,"productType":"n8n-workflow","workflowVersion":"1.0.0","settings":[{"key":"business_name","label":"Business name","help":"As your customers know it. Example: Ranime Jemal Agency","type":"text","required":true,"maxLength":300},{"key":"business_description","label":"What your business does","help":"One or two sentences the AI uses to write in your name. Example: We build AI automations for small businesses in France and Tunisia.","type":"textarea","required":true,"maxLength":2000},{"key":"ideal_customer","label":"Your ideal customer","help":"Who is a good fit: industry, size, need, budget. Example: Real-estate agencies with 5 to 50 agents that want more qualified buyers.","type":"textarea","required":true,"maxLength":2000},{"key":"sender_name","label":"Sender name on emails","help":"The name people see in their inbox. Example: Sarah from Maison Lina","type":"text","required":true,"maxLength":300},{"key":"booking_link","label":"Booking link","help":"Where leads book a call with you, e.g. your Calendly or Google Calendar booking page.","type":"url","required":true},{"key":"team_email","label":"Your team's email","help":"Where alerts and copies are sent. Example: hello@yourbusiness.com","type":"email","required":true},{"key":"google_sheet_url","label":"Google Sheet link","help":"Create an empty Google Sheet, add the tabs from the guide, then copy the link from your browser's address bar and paste it here.","type":"url","required":true},{"key":"auto_send_replies","label":"Send the first reply automatically","help":"On: the AI's reply is sent right away. Off: it is saved as a Gmail draft for you to check first (recommended for the first days).","type":"boolean","required":false,"default":true},{"key":"follow_up_days","label":"Days between follow-ups","help":"How long to wait before reminding a lead who has not answered.","type":"number","required":false,"min":1,"max":30,"default":2},{"key":"max_follow_ups","label":"Maximum follow-ups per lead","help":"After this many reminders, the lead is left alone.","type":"number","required":false,"min":0,"max":10,"default":3}]}$m$::jsonb, array['Web form (included)', 'Gmail', 'OpenAI', 'Google Sheets', 'Meta Lead Ads (optional)'], 'An n8n account (n8n Cloud or your own n8n, version 1.123 or newer) and your own Gmail, OpenAI and Google Sheets accounts. Optional: Meta Lead Ads.'),
  ('ai-customer-service-chatbot', $m${"schemaVersion":1,"productType":"n8n-workflow","workflowVersion":"1.0.0","settings":[{"key":"business_name","label":"Business name","help":"As your customers know it. Example: Ranime Jemal Agency","type":"text","required":true,"maxLength":300},{"key":"business_description","label":"What your business does","help":"One or two sentences the AI uses to write in your name. Example: We build AI automations for small businesses in France and Tunisia.","type":"textarea","required":true,"maxLength":2000},{"key":"opening_hours","label":"Opening hours","help":"Example: Monday to Friday, 9:00 to 18:00","type":"text","required":true,"maxLength":300,"default":"Monday to Friday, 9:00 to 18:00"},{"key":"contact_details","label":"How customers can reach a person","help":"Email and/or phone the chatbot gives when it hands over. Example: support@yourbusiness.com, +216 00 000 000","type":"text","required":true,"maxLength":300},{"key":"tone","label":"Tone of the answers","help":"Example: friendly, short and clear","type":"text","required":false,"maxLength":300,"default":"friendly, short and clear"},{"key":"team_email","label":"Your team's email","help":"Where alerts and copies are sent. Example: hello@yourbusiness.com","type":"email","required":true},{"key":"google_sheet_url","label":"Google Sheet link","help":"Create an empty Google Sheet, add the tabs from the guide, then copy the link from your browser's address bar and paste it here.","type":"url","required":true}]}$m$::jsonb, array['Website chat (included)', 'OpenAI', 'Google Sheets', 'Gmail'], 'An n8n account (n8n Cloud or your own n8n, version 1.123 or newer) and your own OpenAI, Google Sheets and Gmail accounts.'),
  ('ai-appointment-booking', $m${"schemaVersion":1,"productType":"n8n-workflow","workflowVersion":"1.0.0","settings":[{"key":"business_name","label":"Business name","help":"As your customers know it. Example: Ranime Jemal Agency","type":"text","required":true,"maxLength":300},{"key":"services","label":"Your services and their length","help":"Separated by commas. Example: Haircut (45 min), Colour (90 min), Consultation (30 min)","type":"textarea","required":true,"maxLength":2000},{"key":"address","label":"Address","help":"Given to customers when they book.","type":"text","required":true,"maxLength":300},{"key":"calendar_id","label":"Google Calendar to use","help":"Leave \"primary\" to use your main calendar. For another calendar: Google Calendar, Settings, the calendar, Integrate calendar, Calendar ID.","type":"text","required":true,"maxLength":300,"default":"primary"},{"key":"timezone","label":"Time zone","help":"Example: Africa/Tunis, Europe/Paris, Europe/London, America/New_York","type":"text","required":true,"maxLength":300,"default":"Europe/Paris"},{"key":"open_days","label":"Open days","help":"Example: Monday to Saturday","type":"text","required":true,"maxLength":300,"default":"Monday to Saturday"},{"key":"open_time","label":"Opening time","help":"24-hour format. Example: 09:00","type":"text","required":true,"maxLength":300,"default":"09:00"},{"key":"close_time","label":"Closing time","help":"24-hour format. Example: 18:00","type":"text","required":true,"maxLength":300,"default":"18:00"},{"key":"slot_minutes","label":"Length of an appointment (minutes)","help":"Example: 30 or 60","type":"number","required":false,"min":5,"max":480,"default":60},{"key":"reminder_hours_before","label":"Send the reminder this many hours before","help":"24 means the day before.","type":"number","required":false,"min":1,"max":168,"default":24},{"key":"sender_name","label":"Sender name on emails","help":"The name people see in their inbox. Example: Sarah from Maison Lina","type":"text","required":true,"maxLength":300}]}$m$::jsonb, array['Website chat (included)', 'OpenAI', 'Google Calendar', 'Gmail'], 'An n8n account (n8n Cloud or your own n8n, version 1.123 or newer) and your own OpenAI, Google Calendar and Gmail accounts.'),
