update self_serve s set price_minor = p.price_minor
from (values
  ('ai-lead-generation-follow-up', 30000), ('ai-customer-service-chatbot', 20000), ('ai-appointment-booking', 20000),
  ('ai-social-media-automation', 15000), ('ai-voice-receptionist', 30000), ('ai-document-processing', 30000),
  ('ai-security-monitoring-workflows', 50000), ('ai-lead-management-assistant', 25000), ('lead-enrichment-qualification', 28000),
  ('social-media-content-scheduler', 12000), ('review-reputation-monitor', 18000), ('customer-support-ticket-triage', 26000),
  ('ecommerce-order-inventory-sync', 35000), ('abandoned-cart-recovery', 32000), ('meeting-notes-task-assistant', 15000),
  ('invoice-receipt-data-extraction', 27000), ('website-uptime-incident-notifier', 10000), ('phishing-email-analyzer', 45000),
  ('website-security-ssl-scanner', 22000), ('vulnerability-watch-cve-kev', 40000), ('data-breach-monitor', 30000),
  ('lookalike-domain-monitor', 26000)
) as p (slug, price_minor) where p.slug = s.slug;

do $$
begin
  if (select count(*) from self_serve s join products p on p.slug = s.slug where s.price_minor > 0) <> 22 then
    raise exception 'expected 22 self-serve listings with a price';
  end if;
end $$;

insert into product_versions (product_id, version, changelog, status)
select p.id, '1.0.0', 'First release.', 'approved'
from products p join self_serve s on s.slug = p.slug
where not exists (select 1 from product_versions v where v.product_id = p.id and v.version = '1.0.0');

update product_versions v set status = 'approved'
from products p join self_serve s on s.slug = p.slug
where v.product_id = p.id and v.version = '1.0.0';

insert into product_manifests (version_id, manifest)
select v.id, s.manifest
from products p join self_serve s on s.slug = p.slug join product_versions v on v.product_id = p.id and v.version = '1.0.0'
on conflict (version_id) do update set manifest = excluded.manifest;

update products p set
  current_version_id = v.id,
  price_minor = s.price_minor,
  currency = 'USD',
  quote_only = false,
  customization_mode = 'configurable',
  integrations = s.integrations,
  prerequisites = s.prerequisites,
  install_instructions = $t$Do it yourself, with the guided setup (about 30 minutes, no code):
1. Buy the automation, then open it in My automations.
2. Fill in a short form with your business details: each field explains what to write.
3. Download your automation, with your details already filled in.
4. Import it into your n8n and connect your accounts, following the step-by-step guide.
5. Test it with your own data and switch it on.

Prefer we do it for you? Choose "Done for you": we set it up and test it in your accounts.$t$,
  support_policy = 'Do it yourself: setup help by email and free updates of this version. Done for you: 30 days of fixes after handover, and monthly maintenance on request.',
  updated_at = now()
from self_serve s, product_versions v
where s.slug = p.slug and v.product_id = p.id and v.version = '1.0.0';

drop table self_serve;

-- Who may use an automation's setup tool (form, personal download, sheet templates): its buyers, and the
-- platform's admins, who can open every automation for free (to test and to set up clients' automations).
-- owns_product itself stays "has bought it": it also decides who may leave a review.
create or replace function can_use_product(p_product_id uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select owns_product(p_product_id) or is_admin()
$$;
revoke all on function can_use_product(uuid) from public, anon;
grant execute on function can_use_product(uuid) to authenticated;

-- Buyers save their setup answers themselves (no server secret needed). The server validates the answers against
-- the setup form first; this function only enforces access, size and the revision number.
create or replace function save_configuration(p_product_id uuid, p_values jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  vid uuid;
  rev integer;
  cid uuid;
begin
  if uid is null then raise exception 'sign in first' using errcode = '42501'; end if;
  if not can_use_product(p_product_id) then raise exception 'you do not own this product' using errcode = '42501'; end if;
  if jsonb_typeof(p_values) <> 'object' or length(p_values::text) > 32000 then raise exception 'invalid configuration'; end if;
  select current_version_id into vid from products where id = p_product_id;
  if vid is null then raise exception 'this product has no published version'; end if;
  perform pg_advisory_xact_lock(hashtext(uid::text || p_product_id::text));
  select coalesce(max(revision), 0) + 1 into rev from product_configurations where user_id = uid and product_id = p_product_id;
  insert into product_configurations (user_id, product_id, version_id, revision, values)
  values (uid, p_product_id, vid, rev, p_values) returning id into cid;
  return cid;
end $$;
revoke all on function save_configuration(uuid, jsonb) from public, anon;
grant execute on function save_configuration(uuid, jsonb) to authenticated;

-- The first descriptions of the top listings were written for done-for-you projects and named channels the
-- ready-made workflows do not include (WhatsApp, SMS, Calendly, CRMs, Slack/Teams). They now describe exactly what
-- the workflow does; other channels are offered as done-for-you work.
update products set
  short_description = 'Answers every new lead within minutes, scores it with AI, follows up by email until the lead replies, and alerts you about hot leads.',
  description = $d$Leads go cold when nobody replies within minutes. This automation answers every new lead straight away and keeps following up.

What it does:
- Captures leads from a ready-made web form, from your website or ads tools (webhook), and optionally from Facebook Lead Ads
- Scores each lead hot, warm or cold with AI against your ideal customer
- Writes a personal first reply that invites the lead to book a call, sent at once or saved as a Gmail draft for you to check
- Follows up by email every few days until the lead replies, then stops and tells you
- Records every lead in your Google Sheet and emails you about hot leads

Need WhatsApp follow-up or your CRM (HubSpot, Pipedrive…)? Choose "Done for you" and we add it.

Who buys it: agencies, real estate agents and consultants.$d$
where slug = 'ai-lead-generation-follow-up';

update products set
  short_description = 'A website chatbot that answers customers 24/7 from your own FAQ, in their language, and hands over to your team by email when needed.',
  description = $d$Most customer questions are the same few: delivery, returns, prices, opening hours. This chatbot answers them instantly from your own content.

What it does:
- Answers on your website chat, 24/7 and in the customer's language
- Answers only from your FAQ sheet, so it never makes up prices or policies
- When a customer asks for a person, is upset or needs something it cannot do, it takes their contact details and emails your team
- Logs every question and answer in your Google Sheet, so you see what customers ask most and can improve your FAQ

Need it on WhatsApp or Instagram, or order lookups in Shopify? Choose "Done for you" and we add it.

Who buys it: e-commerce stores and service businesses.$d$
where slug = 'ai-customer-service-chatbot';

update products set
  short_description = 'A booking chat that checks your real Google Calendar, books, moves and cancels appointments, and emails reminders to cut no-shows.',
  description = $d$Phone tag and no-shows cost appointment businesses hours every week. This automation books clients into your real calendar and reminds them.

What it does:
- A chat on your website offers free times from your Google Calendar, inside your opening hours
- Books the appointment with the service, name, email and phone; the client gets a calendar invitation
- Finds a client's booking by email to move or cancel it
- Emails a reminder before each appointment (24 hours before by default)

Need WhatsApp or SMS reminders, or Calendly? Choose "Done for you" and we add it.

Who buys it: salons, clinics and consultants.$d$
where slug = 'ai-appointment-booking';

update products set
  short_description = 'The back office of an AI phone receptionist (Vapi): checks your calendar, books appointments, takes messages and emails you a summary of every call.',
  description = $d$Missed calls are missed bookings. With a Vapi voice agent and this automation, every call is answered, day and night.

What it does:
- The voice agent runs on Vapi (voice, speech recognition, phone number); a ready-made assistant configuration is included
- Checks free times in your Google Calendar, inside your opening hours
- Books appointments into your calendar after checking the time is still free
- Takes messages and emails them to your team with the caller's number
- Logs every call (summary, transcript, recording link) in your Google Sheet and emails you the summary

Want transfers to your staff or a different booking system? Choose "Done for you".

Who buys it: hotels, restaurants and service businesses.$d$
where slug = 'ai-voice-receptionist';

update products set
  short_description = 'Reads invoices and receipts (PDF or photo) from email or an upload form, extracts and checks the data, files them in Google Drive and logs them in Google Sheets.',
  description = $d$Typing data from documents is slow and error-prone. This automation extracts it for you and flags anything that needs a human check.

What it does:
- Collects invoices and receipts from your email (PDF, JPG, PNG) or a shareable upload form
- Extracts supplier, VAT ID, invoice number, dates, currency, subtotal, VAT, total and line items with AI, including scans and photos
- Checks that the amounts add up and flags missing or unusual values for review
- Files each document in Google Drive with a consistent name and logs it in your Google Sheet
- Emails your team about anything that needs review

Need the data sent to Xero, QuickBooks or your CRM? Choose "Done for you" and we add it.

Who buys it: accounting firms and property businesses.$d$
where slug = 'ai-document-processing';

update products set
  short_description = 'Receives alerts from Wazuh, Grafana or AWS GuardDuty, checks IPs on VirusTotal, triages each alert with AI and emails the urgent ones, with a weekly summary.',
  description = $d$Security tools produce more alerts than small teams can read. This automation sorts the noise from what needs action.

What it does:
- Receives alerts from Wazuh, Grafana or Prometheus Alertmanager, AWS GuardDuty, or any tool that can send JSON
- Mutes repeats of the same alert so your inbox is not flooded
- Checks public IP addresses on VirusTotal
- Triages each alert with AI: severity, summary, likely cause, false-positive likelihood and recommended actions
- Logs every alert in your Google Sheet and emails high and critical ones at once
- Emails a weekly summary every Monday

Need Slack or Microsoft Teams alerts, or more sources? Choose "Done for you" and we scope it with you.

Who buys it: businesses with IT infrastructure.$d$
where slug = 'ai-security-monitoring-workflows';

update products set description = replace(description, E'Monthly plan: setup plus content runs, monitoring and adjustments each month.\n\n', E'Done for you: a monthly plan with setup, content runs, monitoring and adjustments each month.\n\n')
where slug = 'ai-social-media-automation';
